head.script:
scwin.screenId = "jldfil10200";

///////// 1. 변수 및 선언 영역 /////////

scwin.designDd = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_spotIsuTrdMktTpCd", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) !== '6'); } }, { id: "c_when_48", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) === '1'); } }, { id: "c_when_71", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "spotIsuTrdMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("spotIsuTrdMktTpCd")) === '2'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.initValue();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil10200.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil10200: 진입 키 popmarket 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil10200.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_LoadNfaithDesignAdvnoti_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_LoadNfaithDesignAdvnoti_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_LoadNfaithDesignAdvnoti_xhr", unresolved: "action:self_submit:tx_fn_LoadNfaithDesignAdvnoti_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_LoadNfaithDesign_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_LoadNfaithDesign_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_LoadNfaithDesign_xhr", unresolved: "action:self_submit:tx_fn_LoadNfaithDesign_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_nfaithDesignCntList_fmt_column1
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_nfaithDesignCntList_fmt_column1 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_nfaithDesignCntList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "designDd") ?? '') : '');
        if (v !== '') { return (console.error('[sdd] 미실현 라벨 갈래: column1 (expression)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_nfaithDesignCntList.column1" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.grd_nfaithDesignCntList_2_fmt_column1
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_nfaithDesignCntList_2_fmt_column1 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_nfaithDesignCntList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "designDd") ?? '') : '');
        if (v !== '') { return (console.error('[sdd] 미실현 라벨 갈래: column1 (expression)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_nfaithDesignCntList_2.column1" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.loadNfaithDesignAdvnoti
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.loadNfaithDesignAdvnoti = async function () {
    /* sdd-asis-lifecycle:begin fn_LoadNfaithDesignAdvnoti — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.nfaithDesignAdvnotiForm || { elements: [] });
    frm.action = "/company/popMarket.do";
    $c.util.getComponent('dma_LoadNfaithDesignAdvnotiXhrReq').set('method', "searchNfaithDesignAdvnoti");
    const result = await scwin.tx_fn_LoadNfaithDesignAdvnoti_xhr();
    (($c.util.getComponent("txt_nfaithAdvnotiDiv")) && ($c.util.getComponent("txt_nfaithAdvnotiDiv")).setValue ? ($c.util.getComponent("txt_nfaithAdvnotiDiv")).setValue(result) : (($c.util.getComponent("txt_nfaithAdvnotiDiv")) ? (($c.util.getComponent("txt_nfaithAdvnotiDiv")).innerHTML = result) : void (result)));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.loadNfaithDesign
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.loadNfaithDesign = async function () {
    /* sdd-asis-lifecycle:begin fn_LoadNfaithDesign — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.nfaithDesignForm || { elements: [] });
    frm.action = "/company/popMarket.do";
    $c.util.getComponent('dma_LoadNfaithDesignAdvnotiXhrReq').set('method', "searchNfaithDesign");
    const result = await scwin.tx_fn_LoadNfaithDesign_xhr();
    (($c.util.getComponent("txt_nfaithDiv")) && ($c.util.getComponent("txt_nfaithDiv")).setValue ? ($c.util.getComponent("txt_nfaithDiv")).setValue(result) : (($c.util.getComponent("txt_nfaithDiv")) ? (($c.util.getComponent("txt_nfaithDiv")).innerHTML = result) : void (result)));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.initValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initValue = async function () {
    /* sdd-asis-lifecycle:begin fn_InitValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.loadNfaithDesignAdvnoti();
    await scwin.loadNfaithDesign();
    /* sdd-asis-lifecycle:end */
};
